<template>
  <el-dialog :style="decorationThemeVariables" title="排行榜 · 全元素编辑" :visible="true" width="1260px" top="3vh" append-to-body :close-on-click-modal="false" @close="$emit('close')">
    <div class="rc-editor-bar"><el-select v-model="section" size="small" @change="selectedId='';scope=-1"><el-option v-for="(name,key) in sectionNames" :key="key" :value="key" :label="name" /></el-select><span>预览名次</span><el-input-number v-model="previewRank" size="small" :min="1" :max="100" /><el-button size="small" @click="json=JSON.stringify(scene,null,2);jsonOpen=true">导入 / 导出配置</el-button><span class="rc-editor-hint">固定坐标按可用宽度整体缩放；超出父容器的内容按裁切选项处理。</span></div>
    <div class="rc-editor-layout">
      <aside class="rc-tree"><div class="rc-add"><el-select v-model="addKind" size="small"><el-option v-for="(label,key) in kinds" :key="key" :label="label" :value="key" /></el-select><el-button size="small" @click="add(false)">添加</el-button></div>
        <p class="rc-layer-hint">点击名称编辑内容与样式；右侧开关控制显示。</p>
        <div v-for="entry in flatNodes" :key="'layer-'+entry.node.id" class="rc-layer-entry" :class="{active:entry.node.id===selectedId}" :data-layer-id="entry.node.id"><button type="button" :style="{paddingLeft:(10+entry.depth*12)+'px'}" @click="selectNode({id:entry.node.id})">{{entry.node.label}}</button><el-switch v-model="entry.node.visible" :aria-label="'显示'+entry.node.label" /></div>
        <el-button v-if="rowNode" class="rc-row-border-button" size="mini" @click="selectNode({id:rowNode.id});panels=['surface']">整行背景与边框</el-button>
        <div v-if="selected" class="rc-tree-actions"><el-button size="mini" @click="duplicate">复制</el-button><el-button size="mini" @click="move(-1)">上移</el-button><el-button size="mini" @click="move(1)">下移</el-button><el-button size="mini" @click="remove">删除</el-button><el-button v-if="['group','products'].includes(selected.kind)" size="mini" @click="add(true)">添加子元素</el-button></div>
        <el-divider>榜单切换标签</el-divider><div v-for="(tab,index) in scene.tabs" :key="'tab-'+index" style="margin-bottom:12px"><el-input v-model="tab.label" size="small" placeholder="标签文字" maxlength="32" /><el-select v-model="tab.rankingId" size="small" filterable remote :remote-method="searchBoards" placeholder="绑定营销榜单"><el-option v-if="index===0" :value="0" label="使用组件主榜单" /><el-option v-for="board in boardOptions" :key="board.id" :value="board.id" :label="board.name" /></el-select><el-button type="text" size="mini" @click="scene.tabs.splice(index,1)">移除标签</el-button></div><el-button size="mini" :disabled="scene.tabs.length>=8" @click="scene.tabs.push({label:'新榜单',rankingId:0})">添加切换标签</el-button>
        <el-divider>画布与区块</el-divider><ranking-fields :value="scene" :fields="frameFields" /><b>字体资源</b><div v-for="(font,index) in scene.fonts" :key="'font-'+index"><el-input v-model="font.family" size="small" placeholder="字体名称，供元素字体引用" /><el-input v-model="font.url" size="small" placeholder="字体文件地址" /><el-button type="text" @click="scene.fonts.splice(index,1)">移除字体</el-button></div><el-button size="mini" :disabled="scene.fonts.length>=6" @click="scene.fonts.push({family:'自定义字体'+(scene.fonts.length+1),url:''})">添加字体资源</el-button><el-form label-position="top" size="small"><el-form-item :label="sectionNames[section]+'高度'"><el-input-number v-model="scene[section].height" :min="0" :max="3000" /></el-form-item><el-form-item v-if="section==='card'" label="卡片间距"><el-input-number v-model="scene.card.gap" :min="0" :max="100" /></el-form-item></el-form>
        <template v-if="section==='card'"><b>按名次覆盖卡片高度</b><div v-for="(rule,index) in scene.card.heights" :key="'height-'+index"><el-input-number v-model="rule.from" size="mini" :min="1" :max="100" /><el-input-number v-model="rule.to" size="mini" :min="rule.from" :max="100" /><el-input-number v-model="rule.height" size="mini" :min="1" :max="3000" /><el-button type="text" @click="scene.card.heights.splice(index,1)">删除</el-button></div><el-button size="mini" :disabled="scene.card.heights.length>=20" @click="scene.card.heights.push({from:previewRank,to:previewRank,height:scene.card.height})">添加高度覆盖</el-button></template>
      </aside>
      <main class="rc-editor-preview"><ranking-canvas :config="previewConfig" :ranking="ranking" :rows="previewRows" :active-board-id="config.rankingId" editing :selected-id="selectedId" @select="selectNode" /></main>
      <aside class="rc-inspector" :key="selectedId"><template v-if="selected"><el-form size="small" label-position="top"><el-form-item label="元素名称"><el-input v-model="selected.label" maxlength="80" /></el-form-item><el-form-item label="显示元素" data-content-field="visible"><el-switch v-model="selected.visible" /></el-form-item>
        <el-form-item v-if="['text','image','button','stars'].includes(selected.kind)" label="显示内容" data-content-field="binding"><el-select v-model="selected.binding" filterable><el-option v-for="(label,key) in bindings" :key="key" :label="label" :value="key" /></el-select></el-form-item>
        <ranking-fields v-if="selected.kind==='image' && !selected.binding" :value="selected" :fields="[{key:'image',label:'图片素材',type:'image'}]" />
        <el-form-item v-if="['text','button'].includes(selected.kind) && !selected.binding" label="静态文案（支持换行、{rank}、{rank:02}）" data-content-field="text"><el-input v-model="selected.text" type="textarea" :rows="3" maxlength="1000" /></el-form-item>
        <el-form-item v-if="selected.binding" label="指标前缀 / 后缀" data-content-field="affixes"><el-input v-model="selected.prefix" maxlength="100" placeholder="前缀" /><el-input v-model="selected.suffix" maxlength="100" placeholder="后缀" /></el-form-item>
        <el-form-item v-if="selected.binding" label="数值小数位（-1保留原值）" data-content-field="decimals"><el-input-number v-model="selected.decimals" :min="-1" :max="4" /></el-form-item><el-checkbox v-if="selected.binding" v-model="selected.hideWhenEmpty">绑定数据为空时隐藏</el-checkbox>
        <el-form-item v-if="selected.kind!=='tabs'" label="点击行为" data-content-field="action"><el-select v-model="selected.action"><el-option v-for="(label,key) in actions" :key="key" :label="label" :value="key" /></el-select></el-form-item><el-input v-if="selected.action==='link'" v-model="selected.link" placeholder="/pages/... 商城页面地址" />
        <template v-if="selected.kind==='products'"><el-form-item label="店铺内展示商品数"><el-input-number v-model="selected.count" :min="1" :max="6" /></el-form-item><el-checkbox v-if="!selected.productNodes.length" v-model="selected.showProductName">商品名称</el-checkbox><el-checkbox v-if="!selected.productNodes.length" v-model="selected.showProductPrice">商品价格</el-checkbox><el-form-item v-if="!selected.productNodes.length" label="商品图标签，支持 {sales} / {reviews}"><el-input v-model="selected.productCaption" maxlength="100" /></el-form-item></template>
      </el-form>
      <div v-if="section==='card'" class="rc-scope"><b>此元素的名次样式</b><el-select v-model="scope" size="small"><el-option :value="-1" label="基本样式（所有名次）" /><el-option v-for="(rule,index) in selected.rankStyles" :key="index" :value="index" :label="'TOP'+rule.from+'–'+rule.to" /></el-select><el-button size="mini" @click="addRankStyle">添加名次覆盖</el-button><div v-if="scope>=0"><el-input-number v-model="selected.rankStyles[scope].from" size="mini" :min="1" :max="100" /><el-input-number v-model="selected.rankStyles[scope].to" size="mini" :min="selected.rankStyles[scope].from" :max="100" /><el-button type="text" @click="selected.rankStyles.splice(scope,1);scope=-1">删除覆盖</el-button><ranking-fields v-if="selected.kind==='image'" :value="selected.rankStyles[scope]" :fields="[{key:'image',label:'此名次图片覆盖',type:'image'}]" /><el-input v-if="['text','button'].includes(selected.kind)" :value="selected.rankStyles[scope].text" type="textarea" placeholder="此名次文案覆盖（留空可用下方按钮恢复继承）" @input="$set(selected.rankStyles[scope],'text',$event)" /><el-button type="text" @click="$delete(selected.rankStyles[scope],'image');$delete(selected.rankStyles[scope],'text')">恢复继承图片 / 文案</el-button><p>未修改的属性继承基本样式。</p></div></div>
      <el-collapse v-model="panels"><el-collapse-item title="位置、尺寸与层级" name="position"><ranking-fields :value="styleValue" :fields="shownPositionFields" :on-update="setStyle" /></el-collapse-item><el-collapse-item title="背景、边框、圆角与阴影" name="surface"><p class="rc-layer-hint">边框绘制在图片、文字和子元素上方。宽度设为 0 可关闭。</p><ranking-fields :value="styleValue" :fields="shownSurface" :on-update="setStyle" /></el-collapse-item><el-collapse-item v-if="['text','button','tabs','stars'].includes(selected.kind)" title="文字与字体" name="text"><ranking-fields :value="styleValue" :fields="shownText" :on-update="setStyle" /></el-collapse-item><el-collapse-item v-if="['image','products'].includes(selected.kind)" title="图片缩放" name="image"><ranking-fields :value="styleValue" :fields="imageFields" :on-update="setStyle" /></el-collapse-item><el-collapse-item v-if="selected.kind==='tabs'" title="选中标签样式" name="tabs"><ranking-fields :value="styleValue" :fields="tabFields" :on-update="setStyle" /></el-collapse-item><el-collapse-item v-if="selected.kind==='products'" title="商品组布局与文字" name="products"><ranking-fields :value="styleValue" :fields="shownProductFields" :on-update="setStyle" /></el-collapse-item><el-collapse-item v-if="selected.kind==='stars'" title="星星底色" name="stars"><ranking-fields :value="styleValue" :fields="starFields" :on-update="setStyle" /></el-collapse-item></el-collapse>
      </template><el-empty v-else description="选择左侧图层或点击预览元素" :image-size="60" /></aside>
    </div>
    <div slot="footer"><el-button @click="$emit('close')">返回装修</el-button><span class="rc-editor-hint">修改会保留在当前页面，使用装修页的“保存”提交。</span></div>
    <el-dialog title="全元素配置 JSON" :visible.sync="jsonOpen" width="800px" append-to-body><el-input v-model="json" type="textarea" :rows="20" /><div slot="footer"><el-button @click="download">导出文件</el-button><el-button type="primary" @click="importJSON">应用配置</el-button></div></el-dialog>
  </el-dialog>
</template>
<script>
import {decorationThemeMixin} from '../../../../shared/themeColors';
import productPhoto from '@/assets/images/product-diy.png';
import RankingCanvas from './RankingCanvas';import RankingFields from './RankingFields';
import { canvasKinds,canvasBindings,canvasNode,normalizeCanvas,assertCanvas } from '../../../../shared/rankingCanvas';
import { rankingList } from '@/api/ranking';
import * as controls from './rankingCanvasControls';
export default {mixins:[decorationThemeMixin],components:{RankingCanvas,RankingFields},props:{config:Object,ranking:{type:Object,default:()=>({name:'排行榜',description:'示例数据'})},rows:{type:Array,default:()=>[]}},data(){return{boardOptions:[],section:'card',selectedId:'',addKind:'text',scope:-1,previewRank:1,json:'',jsonOpen:false,panels:['position'],sectionNames:{header:'榜头与切换区',card:'循环榜单卡片',footer:'页尾',empty:'空状态'},kinds:canvasKinds,bindings:canvasBindings,actions:{none:'无操作',product:'商品详情',shop:'店铺首页',ranking:'完整榜单',rules:'榜单规则',back:'返回上一页',link:'商城链接'},...controls};},created(){this.searchBoards('');},computed:{scene(){return this.config.appearance.canvas;},flatNodes(){const result=[];const walk=(nodes,depth)=>nodes.forEach((node,index)=>{result.push({node,nodes,index,depth});walk(node.children,depth+1);walk(node.productNodes||[],depth+1);});walk(this.scene[this.section].nodes,0);return result;},rowNode(){return this.section==='card'&&this.scene.card.nodes.find(n=>n.kind==='group'&&n.style.width>=this.scene.designWidth-20&&n.style.height>=this.scene.card.height-20);},entry(){return this.flatNodes.find(e=>e.node.id===this.selectedId);},selected(){return this.entry&&this.entry.node;},styleValue(){if(!this.selected)return{};return{...this.selected.style,...(this.scope>=0?this.selected.rankStyles[this.scope].style:{})};},shownPositionFields(){return this.selected.kind==='group'?this.positionFields.filter(f=>!['paddingX','paddingY'].includes(f.key)):this.positionFields;},shownSurface(){const v=this.styleValue;return this.surfaceFields.filter(f=>!(f.key==='background2'||f.key==='angle')||v.backgroundMode==='gradient').filter(f=>!['backgroundImage','backgroundFit','backgroundPosition'].includes(f.key)||v.backgroundMode==='image').filter(f=>!['borderColor','borderStyle'].includes(f.key)||v.borderWidth>0).filter(f=>!['shadowColor','shadowX','shadowY','shadowBlur'].includes(f.key)||v.shadow);},shownProductFields(){return this.selected.productNodes.length?this.productFields.filter(f=>['columns','gap','productDesignWidth','productItemHeight'].includes(f.key)):this.productFields;},shownText(){const fields=this.selected.kind==='stars'?this.textFields.filter(f=>['color','fontSize','fontWeight','fontFamily','letterSpacing','verticalAlign'].includes(f.key)):this.selected.kind==='tabs'?this.textFields.filter(f=>!['lines','textAlign','verticalAlign'].includes(f.key)):this.textFields;return fields.filter(f=>!['textShadowColor','textShadowX','textShadowY','textShadowBlur'].includes(f.key)||this.styleValue.textShadow);},previewConfig(){return{...this.config,limit:1};},previewRows(){const item=this.rows[0]||{id:1,name:'商品 / 店铺示例',image:productPhoto,price:'129.00',rank:1,sales:200,reviews:60,rating_score:4.8,score:98.5,products:[1,2,3].map(id=>({id,name:'示例商品',image:productPhoto,price:'129.00',sales:100}))};return[{...item,rank:this.previewRank}];}},methods:{async searchBoards(keyword){try{this.boardOptions=(await rankingList({keyword,limit:100})).data.list;}catch(e){this.$message.error(e.msg||'榜单读取失败');}},selectNode(value){this.section=value.section||this.section;this.selectedId=value.id||value;this.previewRank=value.rank||this.previewRank;this.scope=-1;this.panels=['position','text'];},add(child){const node=canvasNode(this.addKind,{label:this.kinds[this.addKind],text:this.addKind==='text'?'请输入文案':''});(child?(this.selected.kind==='products'?this.selected.productNodes:this.selected.children):this.scene[this.section].nodes).push(node);this.selectedId=node.id;this.scope=-1;},duplicate(){const copy=JSON.parse(JSON.stringify(this.selected));const ids=node=>{node.id=canvasNode().id;node.children.forEach(ids);(node.productNodes||[]).forEach(ids);};ids(copy);copy.label+=' 副本';copy.style.x+=8;copy.style.y+=8;this.entry.nodes.splice(this.entry.index+1,0,copy);this.selectedId=copy.id;this.scope=-1;},remove(){this.entry.nodes.splice(this.entry.index,1);this.selectedId='';},move(delta){const e=this.entry,next=e.index+delta;if(next<0||next>=e.nodes.length)return;const node=e.nodes.splice(e.index,1)[0];e.nodes.splice(next,0,node);},setStyle(key,value){const target=this.scope<0?this.selected.style:this.selected.rankStyles[this.scope].style;this.$set(target,key,key==='fontWeight'?Number(value):value);},addRankStyle(){if(this.selected.rankStyles.length>=20)return;this.selected.rankStyles.push({from:this.previewRank,to:this.previewRank,style:{}});this.scope=this.selected.rankStyles.length-1;},importJSON(){try{const value=JSON.parse(this.json);assertCanvas(value);this.$set(this.config.appearance,'canvas',normalizeCanvas(value));this.selectedId='';this.scope=-1;this.jsonOpen=false;}catch(e){this.$message.error(e.message||'配置格式不正确');}},download(){const url=URL.createObjectURL(new Blob([this.json],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ranking-canvas.json';a.click();URL.revokeObjectURL(url);}}};
</script>
<style scoped>.rc-editor-layout{display:grid;grid-template-columns:260px 375px 1fr;gap:20px;height:68vh}.rc-tree,.rc-inspector{overflow:auto;padding:10px;background:#fff;border:1px solid #eee}.rc-editor-preview{overflow:auto;background:#f3f3f3;align-self:stretch}.rc-editor-preview>p{font-size:11px;padding:10px;color:#999}.rc-layer-entry{display:flex;align-items:center;gap:8px;padding-right:8px}.rc-layer-entry>button{flex:1;min-width:0;text-align:left;background:transparent;border:0;padding:9px;color:#555;cursor:pointer}.rc-layer-entry.active{background:#eaf3ff;color:#1677ff}.rc-layer-entry.active>button{color:inherit}.rc-layer-hint{font-size:12px;color:#909399;line-height:1.6}.rc-row-border-button{margin:10px 0}.rc-add{display:flex;gap:5px;margin-bottom:10px}.rc-tree-actions{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px}.rc-tree-actions .el-button{margin:0}.rc-editor-bar{display:flex;align-items:center;gap:10px;margin-bottom:15px;font-size:12px}.rc-editor-bar>.el-select{width:150px}.rc-editor-bar>.el-input-number{width:120px}.rc-editor-hint{font-size:12px;color:#999;margin-left:10px}.rc-scope{padding:10px;background:#f5f7fa;font-size:12px}.rc-scope .el-select{width:100%;margin:8px 0}.rc-scope .el-input-number{width:110px}.rc-scope p{color:#999;font-size:11px}.rc-inspector /deep/ .el-collapse-item__header{font-size:13px}</style>
